    return all((a | b) in members for a in family for b in family)

def verify(n: int) -> tuple[int, int]:
    checked = counterexamples = 0
    for family in families(n):
        if not any(family) or not is_union_closed(family):
            continue
        checked += 1
        active = 0
        for a in family: active |= a
        good = any(active & (1 << x) and
                   2 * sum(bool(a & (1 << x)) for a in family) >= len(family)
                   for x in range(n))
        counterexamples += not good
    return checked, counterexamples

if __name__ == "__main__":
