from __future__ import annotations
from math import log

def divergence(a: float, b: float) -> float:
    if a <= 0 or b <= 0: raise ValueError("positive rates required")
    return log(a / b) + b / a - 1.0

def compare(n: int) -> tuple[float, float]:
    information = sum(divergence(k + 1.0, k + 2.0) for k in range(n))
    harmonic = sum(1.0 / j for j in range(1, n + 1)) - log(n + 1.0)
    return information, harmonic

if __name__ == "__main__":
    for n in (1, 10, 100, 1000): print(n, compare(n))

