from __future__ import annotations

def closure_and_top(generators: set[int]) -> tuple[set[int], int]:
    family = set(generators)
    changed = True
    while changed:
        changed = False
        for a in tuple(family):
            for b in tuple(family):
                union = a | b
                if union not in family:
                    family.add(union); changed = True
    top = 0
    for a in family: top |= a
    return family, top

if __name__ == "__main__":
    family, top = closure_and_top({0b001, 0b110})
    print(sorted(family), bin(top), top in family)

