        for i, m in enumerate(masks): pos[m] = (margin + i * gap, size - margin - k * step)
    out = [f'<svg xmlns="http://www.w3.org/2000/svg" width="{size}" height="{size}">',
           '<rect width="100%" height="100%" fill="#081526"/>']
    for m in range(1 << n):
        for bit in range(n):
            q = m | (1 << bit)
            if q != m and m.bit_count() + 1 == q.bit_count():
                x1,y1=pos[m]; x2,y2=pos[q]; out.append(f'<line x1="{x1}" y1="{y1}" x2="{x2}" y2="{y2}" stroke="#31506f"/>')
    for m,(x,y) in pos.items():
        out.append(f'<circle cx="{x}" cy="{y}" r="15" fill="#49d6c8"/><text x="{x}" y="{y+4}" text-anchor="middle" font-size="9">{m}</text>')
    out.append('</svg>'); open(path, 'w', encoding='utf-8').write(''.join(out))
if __name__ == "__main__": make_svg()

