def make_svg(path: str = "cube_frequencies.svg") -> None:
    n, width, height = 8, 720, 420
    vals = [2 ** (n - 1)] * n
    out = [f'<svg xmlns="http://www.w3.org/2000/svg" width="{width}" height="{height}">', '<rect width="100%" height="100%" fill="#fffaf2"/>']
    for i,v in enumerate(vals):
