        out += [f'<rect x="{x}" y="{350-h}" width="52" height="{h}" rx="6" fill="#6c63ff"/>', f'<text x="{x+26}" y="375" text-anchor="middle">x{i}</text>', f'<text x="{x+26}" y="{340-h}" text-anchor="middle">{v}</text>']
    out.append('</svg>'); open(path,'w',encoding='utf-8').write(''.join(out))
